    expect(reply.body.error, 'MCP must not return a JSON-RPC error').toBeUndefined();
    expect(reply.body.result?.isError, 'MCP must not return a tool error').not.toBe(true);
    const content = reply.body.result.content;
    const data = Array.isArray(content) ? JSON.parse(content.find(item => item.type === 'text').text) : content;
    expect(data?.error, 'Tool content must not contain an error').toBeUndefined();
    return data;
  };
  const adminTool = async (tool: string, args: unknown) => unpack(await rpc('/mcp', 'tools/call',
    { name: tool, arguments: args }, process.env.SECMAN_MCP_KEY!, process.env.SECMAN_ADMIN_EMAIL!));
  try {
    const group = await adminTool('create_workgroup', { name });
    await adminTool('assign_users_to_workgroup', { workgroupId: group.id, userIds: [reader.id] });
    const asset = await adminTool('create_asset', { name, type: 'SERVER', owner: name, workgroupIds: [group.id] });
    const hiddenAsset = await adminTool('create_asset', { name: `${name}-hidden`, type: 'SERVER', owner: name });
    const highCve = `CVE-E2E-${suffix}-HIGH`;
    const lowCve = `CVE-E2E-${suffix}-LOW`;
    await adminTool('add_vulnerability', { hostname: name, cve: highCve, criticality: 'HIGH', daysOpen: 7 });
    await adminTool('add_vulnerability', { hostname: name, cve: lowCve, criticality: 'LOW', daysOpen: 2 });
    await adminTool('add_vulnerability', { hostname: `${name}-hidden`, cve: highCve, criticality: 'HIGH', daysOpen: 7 });

    const initialized = await rpc('/mcp', 'initialize', { protocolVersion: '2024-11-05', capabilities: {},
      clientInfo: { name: 'secman-e2e', version: '1.0' } }, readKey.apiKey);
    expect(initialized.body.error).toBeUndefined();
    expect(initialized.body.result.serverInfo.name).toBeTruthy();
    const listed = await rpc('/mcp', 'tools/list', {}, readKey.apiKey, reader.email);
    expect(listed.body.error).toBeUndefined();
    const tool = listed.body.result.tools.find((item: any) => item.name === 'get_vulnerabilities');
    expect(tool, 'Read key must discover get_vulnerabilities').toBeTruthy();
    expect(tool.inputSchema.properties.severity.type).toBe('array');
    expect(tool.inputSchema.properties.severity.items.enum).toContain('High');

    for (const endpoint of ['/mcp', '/api/mcp/tools/call']) {
      const query = async (args: unknown) => unpack(await rpc(endpoint, 'tools/call',
        { name: 'get_vulnerabilities', arguments: args }, readKey.apiKey, reader.email));
      const all = await query({});
      expect(all.vulnerabilities.map((v: any) => v.vulnerabilityId).sort()).toEqual([highCve, lowCve].sort());
      expect(all.vulnerabilities.every((v: any) => v.assetId === asset.id && v.assetName === name)).toBe(true);
      const cve = await query({ cveId: highCve.toLowerCase() });
      expect(cve.vulnerabilities).toHaveLength(1);
      expect(cve.vulnerabilities[0].vulnerabilityId).toBe(highCve);
      expect((await query({ severity: ['High'] })).vulnerabilities.map((v: any) => v.vulnerabilityId)).toEqual([highCve]);
      expect((await query({ assetId: asset.id })).vulnerabilities).toHaveLength(2);
      const first = await query({ page: 0, pageSize: 1 });
      const second = await query({ page: 1, pageSize: 1 });
      expect(first.vulnerabilities).toHaveLength(1);
      expect(second.vulnerabilities).toHaveLength(1);
      expect(first.vulnerabilities[0].id).not.toBe(second.vulnerabilities[0].id);
      const denied = await rpc(endpoint, 'tools/call', { name: 'get_vulnerabilities', arguments: { assetId: hiddenAsset.id } }, readKey.apiKey, reader.email);
      expect(Boolean(denied.body.error || denied.body.result?.isError), 'Direct access to an ungranted asset must be refused').toBe(true);
      for (const [key, email] of [['invalid-key', reader.email], [readKey.apiKey, undefined], [unrelatedKey.apiKey, reader.email]]) {
        const refusal = await rpc(endpoint, 'tools/call', { name: 'get_vulnerabilities', arguments: {} }, key!, email);
        expect(Boolean(refusal.status >= 400 || refusal.body.error || refusal.body.result?.isError), 'Invalid credentials, missing delegate, or missing permission must be refused').toBe(true);
      }
    }
  } finally {
    await client.dispose();
  }
  // The isolated runner removes this run's database and keys even on failure.
});
EOF
